const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = data[0];
const arr = data.slice(1, 1 + n);

const values = [...new Set(arr)];
let answer = n > 0 ? 1 : 0;

for (let i = 0; i < values.length; i++) {
  const a = values[i];

  for (let j = i + 1; j < values.length; j++) {
    const b = values[j];
    let prev = 0;
    let count = 0;

    for (let k = 0; k < n; k++) {
      const v = arr[k];
      if ((v === a || v === b) && v !== prev) {
        count++;
        prev = v;
      }
    }

    if (count > answer) answer = count;
  }
}

console.log(answer);
